// The UI kit for windows: `import { Frame } from 'tilr/ui'` for React, `frame()` and `element()`
// for a window drawn with the DOM. Drawn with the theme's tokens and base classes, so that a
// window built from them looks like the rest of the page. Optional: a window may draw anything
// into its rect (webamp draws Winamp).
//
// The frame has one description (../dom.ts: `FRAME`, `frameControls()`): `<Frame>` renders it,
// `frame()` builds it, `ctx.ui.tile()` uses it, so their markup and `data-call`s are the same.
import type { ReactElement, ReactNode } from 'react'
import { useWindow, useWindowField } from 'tilr/react'
import { FRAME, frameControls } from '../dom.js'

export { element, frame, frameControls, FRAME } from '../dom.js'
export type { FrameControl, FrameOptions, FrameParts, FrameWindow } from '../dom.js'

/**
 * The standard frame: a `.tile` with a title bar (the drag handle), the float / tile and close
 * buttons, and the body. The same markup `frame()` builds for a plugin that does not use React,
 * and `ctx.ui.tile()` gives. `title` defaults to the window's.
 */
export function Frame({ title, controls = true, children }: { title?: string, controls?: boolean, children?: ReactNode }): ReactElement {
  const win = useWindow(['mode', 'modes'])
  const drag = { [FRAME.drag]: '' }
  return (
    <section className={FRAME.tile}>
      <header {...drag}>{title ?? <WindowTitle />}</header>
      {controls && (
        <div className={FRAME.controls}>
          {frameControls(win).map(control => (
            <button key={control.id} type="button" {...{ [`data-${control.id}`]: '' }} aria-label={control.label} data-call={control.call} onClick={() => control.run()}>{control.text}</button>
          ))}
        </div>
      )}
      <div className={FRAME.body}>{children}</div>
    </section>
  )
}

function WindowTitle(): ReactElement {
  const title = useWindowField('title')
  return <>{title}</>
}
